insert into public.training_questions (lesson_no, question_no, question, model_answer, rubric) values
  (1, 1, 'ما المقصود بالعمل بشكل احترافي في مشروع DXN؟', 'فهم الأساسيات ثم تحويل المعرفة إلى تطبيق منتظم مع متابعة وتطوير مستمر.', 'يفرق بين المعرفة والتطبيق.'),
  (1, 2, 'لماذا يبدأ العضو بالتعلم قبل التحدث مع الآخرين؟', 'حتى يتحدث بثقة ودقة ويقدم معلومات صحيحة بدل التخمين.', 'المعرفة والثقة والدقة.'),
  (1, 3, 'ما الفرق بين مشاهدة التدريب وتطبيقه؟', 'المشاهدة تكتسب المعرفة، أما التطبيق فيحوّلها إلى سلوك ونتيجة قابلة للقياس.', 'تمييز واضح.'),
  (1, 4, 'كيف ترتب أولويات العضو الجديد في مرحلة التأسيس؟', 'التعلم، فهم المنتجات والعمل، التدريب، التطبيق، المتابعة، ثم التطوير.', 'ترتيب منطقي.'),
  (1, 5, 'لماذا تدوين أهم النقاط أثناء التدريب مفيد؟', 'لأنه يثبت المعلومات ويجعلها مرجعًا للمراجعة والتطبيق.', 'فائدة عملية.'),
  (1, 6, 'ماذا تفعل إذا لم تعرف إجابة سؤال من شخص مهتم؟', 'أعترف بعدم التأكد وأرجع إلى مصدر موثوق ثم أجيب.', 'عدم التخمين.'),
  (1, 7, 'كيف تجعل يومك التدريبي منتجًا وليس مجرد مشاهدة؟', 'أحدد هدفًا للتعلم ثم أطبق خطوة عملية وأسجل النتيجة.', 'تعلم + تطبيق.'),
  (1, 8, 'كيف تعرف أنك بدأت تتحول من متعلم إلى ممارس؟', 'عندما أشرح الأساسيات وأنفذ الخطوات وأتابع النتائج وأصحح الأخطاء.', 'مؤشرات عملية.'),
  (1, 9, 'ماذا يعني الاستمرار المهني عند بطء النتائج؟', 'الاستمرار في الخطوات الصحيحة مع قياس الأداء وتصحيح الأخطاء.', 'استمرار منضبط.'),
  (1, 10, 'اذكر ثلاثة أخطاء يجب أن يتجنبها العضو الجديد.', 'البدء دون تعلم، إعطاء معلومات غير مؤكدة، والاكتفاء بالمشاهدة دون تطبيق.', 'ثلاثة أخطاء صحيحة.'),
  (2, 1, 'ما الفئات العامة التي ينبغي أن يتعرف إليها العضو في منتجات DXN؟', 'المشروبات والأغذية والمكملات ومنتجات العناية الشخصية والبشرة وغيرها وفق الكتالوج الرسمي.', 'تصنيف عام صحيح.'),
  (2, 2, 'لماذا يجب فهم طريقة استخدام المنتج قبل شرحه؟', 'لتقديم معلومات دقيقة وتجنب الاستخدام الخاطئ.', 'ربط المعرفة بالمسؤولية.'),
  (2, 3, 'ما الفرق بين وصف خصائص المنتج والادعاء بعلاج مرض؟', 'الوصف يعتمد على المعلومات المعلنة، أما الوعد بعلاج مرض فهو ادعاء طبي لا يجوز تقديمه دون أساس مناسب.', 'تمييز مهني.'),
  (2, 4, 'كيف تختار منتجًا لشخص يسأل عنه؟', 'أفهم حاجته ثم أعرض المعلومات الرسمية المتعلقة بالمنتج وأحيله لمختص عند السؤال الطبي.', 'منهج آمن.'),
  (2, 5, 'ما المعلومات الأساسية التي يجب معرفتها عن أي منتج؟', 'اسمه وفئته وخصائصه أو مكوناته المعلنة وطريقة الاستخدام والتحذيرات والتوفر.', 'أربع نقاط أو أكثر.'),
  (2, 6, 'ماذا تفعل عند عدم التأكد من فائدة صحية لمنتج؟', 'لا أخمّن؛ أرجع إلى المصدر الرسمي أو المختص.', 'التحقق.'),
  (2, 7, 'لماذا لا يكفي حفظ أسماء المنتجات؟', 'لأن التواصل يحتاج فهم الاستخدام والخصائص والإجابة عن الأسئلة.', 'فهم لا حفظ فقط.'),
  (2, 8, 'كيف تشرح منتجًا في دقيقة؟', 'أفهم الحاجة ثم أذكر المنتج وفئته وميزته المعلنة وطريقة استخدامه بإيجاز.', 'شرح منظم.'),
  (2, 9, 'كيف تستفيد من تجربة المنتج دون مبالغة؟', 'أصف تجربتي الشخصية بوضوح ولا أحولها إلى وعد بنتيجة مضمونة للآخرين.', 'تمييز التجربة عن الضمان.'),
  (2, 10, 'ما القاعدة الأساسية عند الحديث عن المنتجات الصحية؟', 'الالتزام بالمعلومات الموثوقة وعدم التشخيص أو تقديم وعود علاجية.', 'قاعدة سلامة.'),
  (3, 1, 'ما الفكرة الرئيسية التي خرجت بها من التدريب الثالث؟', 'يذكر العضو الفكرة المركزية كما فهمها مع مثال أو دليل من الفيديو.', 'ارتباط مباشر بالمحتوى.'),
  (3, 2, 'اذكر ثلاث نقاط رئيسية من التدريب الثالث.', 'ثلاث نقاط واضحة وردت في الفيديو مع ترتيب منطقي.', 'ثلاث نقاط من الفيديو.'),
  (3, 3, 'ما المفهوم الجديد الذي تعلمته؟', 'يشرح مفهومًا جديدًا بأسلوبه الخاص دون نسخ العبارة فقط.', 'فهم شخصي.'),
  (3, 4, 'ما المثال العملي الأهم في التدريب؟', 'يذكر مثالًا من الفيديو ويشرح الدرس المستفاد منه.', 'مثال + درس.'),
  (3, 5, 'ما الخطأ الذي يحذر منه التدريب؟', 'يذكر الخطأ كما ورد في الفيديو ويشرح أثره.', 'تحديد صحيح.'),
  (3, 6, 'كيف تطبق فكرة واحدة من التدريب خلال أسبوع؟', 'يحوّل الفكرة إلى خطوة عملية محددة وقابلة للمتابعة.', 'إجراء قابل للقياس.'),
  (3, 7, 'ما السؤال الذي كان يمكن أن تسأله للمدرب بعد التدريب؟', 'سؤال مرتبط مباشرة بنقطة تحتاج إلى توضيح أو تطبيق.', 'سؤال ذكي مرتبط بالمحتوى.'),
  (3, 8, 'ما النقطة التي تحتاج إلى مراجعة ثانية ولماذا؟', 'يحدد نقطة من الفيديو ويذكر سبب حاجته للمراجعة.', 'وعي بالفجوة.'),
  (3, 9, 'كيف تشرح أهم فكرة في التدريب لشخص لم يشاهده؟', 'يلخص الفكرة بلغة بسيطة ثم يعطي مثالًا من المحتوى.', 'تلخيص وفهم.'),
  (3, 10, 'ما السلوك العملي الذي ينبغي أن يتغير بعد هذا التدريب؟', 'يحدد سلوكًا محددًا مستندًا إلى محتوى الفيديو وكيف سيطبقه.', 'تحويل التعلم إلى سلوك.'),
  (4, 1, 'ما المقصود بمشروع DXN كما يقدمه التدريب؟', 'يشرح العضو فكرة المشروع وطبيعته ومكوناته الأساسية كما وردت في التدريب.', 'فهم الفكرة العامة.'),
  (4, 2, 'ما الذي يجعل معرفة الشركة مهمة قبل العمل معها؟', 'تساعد على فهم المنتجات والنظام والفرصة والتحدث بمعلومات صحيحة.', 'أهمية المعرفة.'),
  (4, 3, 'ما العناصر التي يجب أن يعرفها العضو عن الشركة؟', 'نشاط الشركة ومنتجاتها ونظام العمل والأنظمة والسياسات الأساسية.', 'عدة عناصر صحيحة.'),
  (4, 4, 'كيف تشرح فكرة المشروع لشخص لأول مرة؟', 'أبدأ بحاجته ثم أشرح الفكرة باختصار ووضوح وأترك له فرصة طرح الأسئلة.', 'عرض غير معقد.'),
  (4, 5, 'لماذا يجب عدم تقديم وعود مالية مضمونة؟', 'لأن النتائج تعتمد على العمل والمهارة والظروف ولا يصح ضمان دخل محدد.', 'واقعية.'),
  (4, 6, 'ما الفرق بين تعريف الشخص بالمشروع والضغط عليه للانضمام؟', 'التعريف يقدم معلومات ويفتح باب القرار، أما الضغط فيسلبه حرية الاختيار.', 'تمييز واضح.'),
  (4, 7, 'كيف تتحقق من معلومة عن الشركة قبل نشرها؟', 'أرجع إلى مصدر رسمي أو وثيقة موثوقة.', 'التحقق.'),
  (4, 8, 'ما أهم سؤالين يجب أن تكون قادرًا على الإجابة عنهما عن الشركة؟', 'ما طبيعة نشاطها؟ وكيف يعمل العضو ضمن النظام؟ مع إجابات دقيقة.', 'أسئلة جوهرية.'),
  (4, 9, 'كيف تتعامل مع معلومة متداولة لا تجدها في مصدر رسمي؟', 'لا أقدمها كحقيقة وأوضح أنها غير مؤكدة حتى أتحقق منها.', 'أمانة معلوماتية.'),
  (4, 10, 'ما الذي يجعل عرض المشروع احترافيًا؟', 'الوضوح والصدق والاختصار وفهم احتياج الطرف الآخر وعدم المبالغة.', 'معايير احتراف.'),
  (5, 1, 'ما الهدف من المتابعة الفعالة مع الشريك المحتمل؟', 'مساعدته على اتخاذ الخطوة التالية وفهم ما يحتاجه بدل ترك التواصل بلا متابعة.', 'هدف المتابعة.'),
  (5, 2, 'ما الفرق بين المتابعة والإلحاح؟', 'المتابعة تضيف قيمة وتراعي التوقيت، أما الإلحاح فيضغط على الشخص دون مراعاة موقفه.', 'تمييز واضح.'),
  (5, 3, 'متى تكون المتابعة مناسبة؟', 'بعد إعطاء معلومة أو عرض أو وعد بالرد، وفي وقت متفق عليه أو مناسب.', 'توقيت منطقي.'),
  (5, 4, 'ما أول شيء تفعله في متابعة شخص شاهد العرض؟', 'أسأله عن انطباعه وما النقطة التي تحتاج إلى توضيح.', 'سؤال مفتوح.'),
  (5, 5, 'كيف تتعامل مع شخص لم يرد؟', 'أرسل متابعة مختصرة ومحترمة ثم أترك له مساحة ووقتًا مناسبًا.', 'احترام القرار.'),
  (5, 6, 'ماذا تفعل إذا كان لديه اعتراض؟', 'أستمع أولًا وأحدد الاعتراض الحقيقي ثم أجيب بمعلومة مناسبة دون جدال.', 'استماع ثم معالجة.'),
  (5, 7, 'كيف تعرف أن الشريك جاهز للخطوة التالية؟', 'من خلال أسئلته واهتمامه واستعداده لتنفيذ الخطوة المتفق عليها.', 'مؤشرات اهتمام.'),
  (5, 8, 'ما المعلومات التي تسجلها بعد المتابعة؟', 'ما تم شرحه، رد الشخص، اعتراضه، الخطوة التالية وموعد المتابعة إن وجد.', 'توثيق.'),
  (5, 9, 'كيف تجعل المتابعة شخصية وليست رسالة آلية؟', 'أبنيها على آخر نقطة ناقشناها واحتياج الشخص بدل إرسال نفس النص للجميع.', 'تخصيص.'),
  (5, 10, 'ما الخطأ الأكبر في المتابعة؟', 'عدم الاستماع أو تكرار الضغط دون إضافة معلومة أو قيمة جديدة.', 'خطأ واضح.'),
  (6, 1, 'ما المقصود ببناء فريق فعال؟', 'تكوين أعضاء يفهمون العمل ويتدربون ويطبقون ويتابعون بناءً على نظام واضح.', 'فهم الفريق.'),
  (6, 2, 'لماذا لا يكفي جمع عدد كبير من الأعضاء؟', 'لأن قوة الفريق ترتبط بالتفعيل والتدريب والاستمرارية وليس بالعدد وحده.', 'جودة لا عدد.'),
  (6, 3, 'ما دور القائد في بناء الفريق؟', 'التوجيه والتدريب والمتابعة والتحفيز وبناء بيئة تساعد الأعضاء على الاستقلالية.', 'دور متكامل.'),
  (6, 4, 'كيف تساعد العضو الجديد على البداية؟', 'أعطيه خطوات بسيطة وأدربه عليها وأتابع أول تطبيقاته.', 'بداية عملية.'),
  (6, 5, 'ما الفرق بين القائد الذي ينفذ كل شيء والقائد الذي يبني قادة؟', 'الأول يجعل الفريق يعتمد عليه، والثاني يعلم الأعضاء ويمنحهم القدرة على العمل بأنفسهم.', 'الاستقلالية.'),
  (6, 6, 'كيف تبني الثقة داخل الفريق؟', 'بالصدق والالتزام والمتابعة والاحترام والقدوة العملية.', 'عناصر ثقة.'),
  (6, 7, 'ماذا تفعل مع عضو متوقف عن العمل؟', 'أفهم سبب التوقف ثم أحدد معه خطوة صغيرة قابلة للتنفيذ وأتابعها.', 'تشخيص ثم إجراء.'),
  (6, 8, 'كيف تدرب عضوًا على تكرار العمل دون أن تجعله نسخة منك؟', 'أعلمه المبادئ والخطوات وأترك له أسلوبه المناسب ضمن الإطار الصحيح.', 'مبدأ + استقلالية.'),
  (6, 9, 'ما أهمية القدوة في بناء الفريق؟', 'الأعضاء يتعلمون من السلوك العملي للقائد أكثر من الكلام وحده.', 'القدوة.'),
  (6, 10, 'اذكر ثلاث صفات لفريق فعال.', 'التعلم والتطبيق والتواصل والمتابعة والتعاون؛ يذكر ثلاثًا مع تفسير مختصر.', 'ثلاث صفات.'),
  (7, 1, 'ما المقصود بإقفال الدائرة في العمل اليومي؟', 'إكمال دورة العمل من التواصل والعرض إلى المتابعة والنتيجة ثم الانتقال للخطوة التالية.', 'فهم الدائرة.'),
  (7, 2, 'لماذا تحتاج المهام اليومية إلى نظام ثابت؟', 'لأن الانتظام يمنع تشتت الجهد ويجعل النتائج قابلة للقياس.', 'الانتظام.'),
  (7, 3, 'ما المهام اليومية الأساسية التي ينبغي أن يراجعها العضو؟', 'التعلم والتواصل والعرض والمتابعة وخدمة العملاء وبناء الفريق بحسب مرحلته.', 'عدة مهام.'),
  (7, 4, 'كيف تحدد أهم مهمة لليوم؟', 'أختار المهمة الأكثر تأثيرًا على الهدف الحالي وأبدأ بها قبل المهام الأقل أهمية.', 'أولوية.'),
  (7, 5, 'لماذا تسجيل المتابعات مهم؟', 'حتى لا تضيع المواعيد والفرص وتصبح الخطوات التالية واضحة.', 'تنظيم.'),
  (7, 6, 'ماذا تفعل إذا انتهى اليوم دون إنجاز كل المهام؟', 'أراجع السبب وأرحّل المهم غير المكتمل مع ترتيب الأولويات لليوم التالي.', 'مراجعة لا جلد ذات.'),
  (7, 7, 'كيف تقيس نشاطك اليومي؟', 'بعدد الأنشطة المنفذة وجودتها والنتائج والخطوات التالية، لا بمجرد ساعات الانشغال.', 'مؤشرات عملية.'),
  (7, 8, 'ما الفرق بين الانشغال والإنتاجية؟', 'الانشغال قد يستهلك الوقت، أما الإنتاجية فتقاس بما أنجز فعليًا وما نتج عنه.', 'تمييز.'),
  (7, 9, 'كيف تتعامل مع قائمة أشخاص تحتاج إلى متابعة؟', 'أرتبها حسب المرحلة والأولوية وموعد المتابعة وأحدث الحالة بعد كل تواصل.', 'إدارة قائمة.'),
  (7, 10, 'لماذا يجب أن تنتهي كل محادثة بخطوة تالية واضحة؟', 'حتى لا يبقى التواصل مفتوحًا بلا اتجاه ويعرف الطرفان ما سيحدث لاحقًا.', 'خطوة تالية.'),
  (8, 1, 'ما أهم مقدمات بناء فريق فعال؟', 'وضوح الرؤية وفهم طبيعة العمل واختيار الأشخاص المناسبين وتدريبهم ومتابعتهم.', 'عدة مقدمات.'),
  (8, 2, 'كيف تختار الشخص المناسب للفريق؟', 'أبحث عن الاستعداد للتعلم والالتزام والجدية والقدرة على التطبيق، لا عن صفات شكلية فقط.', 'معايير سلوكية.'),
  (8, 3, 'لماذا يجب أن تفهم الشخص قبل أن تعرض عليه العمل؟', 'حتى تعرف احتياجه وهدفه وطريقة التواصل الأنسب معه.', 'فهم الشخص.'),
  (8, 4, 'كيف تبدأ محادثة مهنية مع شخص محتمل؟', 'بحديث طبيعي وسؤال عن اهتمامه واحتياجه ثم الانتقال للمعلومة المناسبة.', 'تدرج.'),
  (8, 5, 'ما الذي يجعل بناء الفريق مستدامًا؟', 'وجود نظام للتدريب والمتابعة والتكرار وبناء أعضاء قادرين على الاستقلالية.', 'استدامة.'),
  (8, 6, 'كيف تتعامل مع رفض شخص للفرصة؟', 'أحترم قراره ولا أحوله إلى خصومة وأترك باب التواصل مفتوحًا عند الحاجة.', 'احترام الرفض.'),
  (8, 7, 'لماذا التركيز على الأشخاص الإيجابيين والمستعدين للتعلم مهم؟', 'لأن وقت القائد محدود والعضو الجاد أكثر قابلية للتطبيق والاستمرار.', 'إدارة الوقت.'),
  (8, 8, 'ما دور التدريب المستمر بعد انضمام العضو؟', 'رفع المعرفة والمهارات وتصحيح الأخطاء ومواكبة التطور.', 'استمرارية التدريب.'),
  (8, 9, 'كيف تحوّل العضو من متلقٍ إلى شريك فعال؟', 'أعطيه معرفة ثم مهمة عملية وأتابع التنفيذ وأساعده على تكرار الخطوات بنفسه.', 'تطبيق واستقلالية.'),
  (8, 10, 'ما العلامة الأهم على أن الفريق بدأ يصبح فعالًا؟', 'ظهور أعضاء يتعلمون ويطبقون ويتابعون ويستطيعون مساعدة أعضاء آخرين.', 'قابلية التكرار.')
